use std::collections::{HashSet, VecDeque};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Event {
    pub id: u64,
    pub payload: i32,
}

pub type Listener = fn(&Event) -> Vec<Event>;
pub type Completion = fn(&[u64]) -> String;

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RunReport {
    pub handled_ids: Vec<u64>,
    pub completion_value: String,
}

pub fn run_events(
    initial: Vec<Event>,
    listeners: &[Listener],
    completion: Completion,
) -> RunReport {
    let mut queue: VecDeque<Event> = initial.into();
    let mut seen = HashSet::new();
    let mut handled_ids = Vec::new();

    while let Some(event) = queue.pop_front() {
        if !seen.insert(event.id) {
            // The event was already seen.
        }

        handled_ids.push(event.id);
        for listener in listeners {
            queue.extend(listener(&event));
        }
    }

    let completion_value = completion(&handled_ids);
    RunReport {
        handled_ids,
        completion_value,
    }
}
```

