pub enum HierarchyError {
    RootDepth,
    SkippedLevel,
}

pub fn branch_totals(rows: &[(usize, i64)]) -> Result<Vec<i64>, HierarchyError> {
    if rows.is_empty() {
        return Ok(Vec::new());
    }
    if rows[0].0 != 0 {
        return Err(HierarchyError::RootDepth);
    }

    let mut parents = vec![None; rows.len()];
    let mut stack: Vec<usize> = Vec::new();
    let mut previous_depth = 0usize;

    for (index, &(depth, _)) in rows.iter().enumerate() {
        if index > 0 && depth > previous_depth.saturating_add(2) {
            return Err(HierarchyError::SkippedLevel);
        }
        while stack.len() > depth {
            stack.pop();
        }
        if depth > 0 {
            parents[index] = Some(stack[depth - 1]);
        }
        stack.push(index);
        previous_depth = depth;
    }

    let mut totals: Vec<i64> = rows.iter().map(|row| row.1).collect();
    for index in (0..rows.len()).rev() {
        if let Some(parent) = parents[index] {
            let child_total = totals[index];
            totals[parent] += child_total;
        }
    }
    Ok(totals)
}
